import { Align, AlignMethod, layoutChain } from "@kvisaz/phaser-sugar";
import { getLocalizedText, ViewElementBuilder } from "../../assets";
import { SceneEvents } from "../../common";
import { FullscreenOverlay } from "../../common/game-core";
import { ConsumableType, mapConsumableRecordToLootDto } from "../../logic";
import { GameServiceProvider } from "../../services";
import { IGameEvents } from "../events";
import { SpiderGameScenes } from "../scenes";
import { finishAdScene, startAdScene } from "../shared/ads";
import { LootEffect } from "../shared";
import {
  ISpiderRewardAdCloseArgs,
  ISpiderRewardAdResult,
  ISpiderRewardAdSceneData,
} from "./types";

/** todo @deprecated уходим в сторону диалогов scenes/dialog **/
export class SpiderRewardAdScene extends Phaser.Scene {
  private parentSceneKey = "";
  private rewardsAmount?: Record<ConsumableType, number>;
  private parentSceneEvents?: SceneEvents<IGameEvents>;
  private overlay?: FullscreenOverlay;
  private lootEffect?: LootEffect;
  private isFinished = false;

  constructor() {
    super(SpiderGameScenes.RewardAd);
  }

  preload() {}

  create(data: ISpiderRewardAdSceneData) {
    this.parentSceneKey = data.parentSceneKey;
    this.rewardsAmount = data.rewardsAmount;
    this.cameras.main.setBackgroundColor("rgba(0,0,0,0)");

    const parentScene = startAdScene({
      scene: this,
      parentSceneKey: this.parentSceneKey,
    });

    this.parentSceneEvents = new SceneEvents<IGameEvents>({ scene: parentScene });
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      this.parentSceneEvents?.unSubscribeAll();
      this.parentSceneEvents = undefined;
      this.clearScene();
    });

    this.createOverlay();
    this.createLootEffect();
    this.lootEffect?.show();
    GameServiceProvider.get().showRewardedAd((result) => this.onAdClose(result));
  }

  private onAdClose(result: ISpiderRewardAdCloseArgs): void {
    if (!result.isReward || !result.wasShown || this.rewardsAmount == null) {
      this.finish({
        ...result,
        rewardsAmount: undefined,
      });
      return;
    }

    const loots = mapConsumableRecordToLootDto(this.rewardsAmount);
    this.lootEffect?.openRandomChest(loots, () => {
      this.finish({
        ...result,
        rewardsAmount: this.rewardsAmount,
      });
    });
  }

  private finish(result: ISpiderRewardAdResult): void {
    if (this.isFinished) {
      return;
    }

    this.isFinished = true;
    this.parentSceneEvents?.emit("gameRewardedAdClosed", result);
    finishAdScene({
      scene: this,
      parentSceneKey: this.parentSceneKey,
      onBeforeStop: () => this.clearScene(),
    });
  }

  private createOverlay(): void {
    const gameService = GameServiceProvider.get();
    this.overlay = new FullscreenOverlay({
      scene: this,
      interactive: true,
      alpha: gameService.getGameConfig().ads.rewardAdOverlayAlpha,
    });

    const builder = new ViewElementBuilder(this);
    const title = builder.textMain(getLocalizedText("ads.reward.title"), {
      fontSize: "48px",
      weight: "bold",
      color: "#ffffff",
    });

    const content = this.add.container(0, 0, [title]);
    layoutChain({
      children: [title],
      alignToNext: AlignMethod.BOTTOM_TO,
      nextOffsetY: 32,
      alignToAnchor: AlignMethod.CENTER,
    });

    const align = new Align();
    align.anchorSceneScreen(this).center(content);
  }

  private createLootEffect(): void {
    const gameService = GameServiceProvider.get();
    this.lootEffect = new LootEffect({
      scene: this,
      lootEffectConfig: gameService.getGameConfig().ads.rewardAdAnimation,
      lootBoxesAmount: 1,
    });
  }

  private clearScene(): void {
    this.overlay?.destroy();
    this.overlay = undefined;
    this.lootEffect?.destroy();
    this.lootEffect = undefined;
    this.children.removeAll(true);
  }
}
