import { Align, arrayAlign } from "@kvisaz/phaser-sugar";
import { getLocalizedText, ViewElementBuilder } from "../../../../../assets";
import { CardSuit, SceneEvents } from "../../../../../common";
import { FireworksEffect } from "../../../../../common/animations";
import { ExternalTopbarDialog } from "../../../../../common/game-core";
import { OverlayScene } from "../../../../../common/scenes";
import { ISpiderGameOverOverlayEvents } from "./events";

interface IProps {
  scene: Phaser.Scene;
}

export class SpiderGameOverOverlay {
  private readonly sceneEvents: SceneEvents<ISpiderGameOverOverlayEvents>;
  private readonly builder: ViewElementBuilder;
  private dialog?: ExternalTopbarDialog;
  private fireworks?: FireworksEffect;
  private isShown = false;

  constructor(private readonly props: IProps) {
    const { scene } = props;
    OverlayScene.attach(scene);
    this.builder = new ViewElementBuilder(OverlayScene.get(scene));
    this.sceneEvents = new SceneEvents<ISpiderGameOverOverlayEvents>({ scene });
    this.sceneEvents.on("spiderGameWin", () => this.showScreen());
  }

  destroy() {
    this.clearScene();
    this.sceneEvents.unSubscribeAll();
  }

  showScreen() {
    if (this.isShown) return;

    const childScene = OverlayScene.get(this.props.scene);
    this.pauseParentScene();
    this.createDialog(childScene);
    this.createFireworks(childScene);
    this.isShown = true;
  }

  closeScreen() {
    this.clearScene();
  }

  private createDialog(scene: Phaser.Scene) {
    const content = this.createDialogContent(scene);
    this.dialog?.destroy();
    this.dialog = this.builder.dialogExternalTopTitle({
      content,
      title: getLocalizedText("gameOver.gameOver"),
      width: 940,
      height: 620,
      onClose: () => this.closeScreen(),
      isCloseOnOverlayClick: false,
    });
    this.dialog.show();
  }

  private createDialogContent(scene: Phaser.Scene) {
    const content = new Phaser.GameObjects.Container(scene);
    const layoutBg = new Phaser.GameObjects.Rectangle(scene, 0, 0, 300, 100);

    const title = this.builder.textDialog(getLocalizedText("gameOver.congratulation"), {
      color: "rgb(0,0,0)",
      weight: "semibold",
      fontSize: "56px",
    });
    const subtitle = this.builder.textDialog(getLocalizedText("gameOver.win"), {
      color: "rgb(251,182,1)",
      weight: "semibold",
      fontSize: "64px",
    });

    const newGameButton = this.builder.buttonPrimary(
      getLocalizedText("spider.gameOver.newGame"),
      () => this.handleNewGameClick(),
      {
        width: 420,
        height: 86,
        fontSizePx: 38,
      },
    );
    const replayButton = this.builder.buttonSecondary(
      getLocalizedText("spider.gameOver.replay"),
      () => this.handleReplayClick(),
      {
        width: 420,
        height: 86,
        fontSizePx: 38,
      },
    );
    const modeSelectButton = this.builder.buttonPrimary(
      getLocalizedText("spider.gameOver.selectMode"),
      () => this.handleModeSelectClick(),
      {
        width: 420,
        height: 86,
        fontSizePx: 38,
      },
    );

    const buttonsAlignObject = arrayAlign.alignObject(
      arrayAlign.column([newGameButton, replayButton, modeSelectButton], 14),
    );

    const queenFigure = this.builder.cardFigure(CardSuit.diamond, "queen");
    const jackFigure = this.builder.cardFigure(CardSuit.heart, "jack");

    const align = new Align();
    align.anchor(layoutBg).centerX(title).topIn(title, -136);
    align.anchor(title).centerX(subtitle).bottomTo(subtitle, 18);
    align.anchor(subtitle).centerX(buttonsAlignObject).bottomTo(buttonsAlignObject, 36);

    align.anchor(layoutBg);
    align.rightTo(queenFigure, -25).centerY(queenFigure);
    align.leftTo(jackFigure, 25).centerY(jackFigure);

    content.add([
      layoutBg,
      title,
      subtitle,
      queenFigure,
      jackFigure,
      newGameButton,
      replayButton,
      modeSelectButton,
    ]);
    return content;
  }

  private clearScene() {
    if (!this.isShown && this.dialog == null && this.fireworks == null) return;

    this.dialog?.destroy();
    this.dialog = undefined;
    this.fireworks?.destroy();
    this.fireworks = undefined;
    this.resumeParentScene();
    this.isShown = false;
  }

  private createFireworks(scene: Phaser.Scene) {
    this.fireworks?.destroy();
    const { textureName, frameNames } = this.builder.getGameFinishFireworksImages();
    this.fireworks = new FireworksEffect({
      scene,
      textureName,
      frameNames,
      particleOptions: {
        scale: { min: 0.6, max: 0.8 },
        rotate: { start: 0, end: 120 },
        quantity: 8,
        lifespan: { min: 1200, max: 2000 },
        speed: { min: 600, max: 1000 },
        gravityY: 560,
        frequency: 1200,
      },
    });
    this.fireworks.start();
  }

  private handleNewGameClick() {
    this.closeScreen();
    this.sceneEvents.emit("uiNewGameClick");
  }

  private handleReplayClick() {
    this.closeScreen();
    this.sceneEvents.emit("uiReplayClick");
  }

  private handleModeSelectClick() {
    this.closeScreen();
    this.sceneEvents.emit("uiModeSelectClick");
  }

  private pauseParentScene() {
    this.props.scene.scene.pause();
  }

  private resumeParentScene() {
    this.props.scene.scene.resume();
  }
}
