import {Align, AlignMethod, layoutChain} from '@kvisaz/phaser-sugar';
import {getLocalizedText, ViewElementBuilder} from '../../assets';
import {ISettingsState} from '../../logic';
import {GameServiceProvider} from '../../services';
import {CommonModal} from '../../common/game-core/components/CommonModal';
import {openCommonModalInScene} from '../../common/game-core';
import {SceneEvents} from '../../common';
import {gameConfig} from '../../config';
import {IGameEvents} from '../events';

interface IProps {
    scene: Phaser.Scene;
}

/**
 * Простая обертка для диалога по этому образцу строй остальные
 * - конструктор - кэшируем создание которое можно кэшировть, подписки
 * - openDialog
 * - createDialog
 *
 * Фокусируй диалоги таким образом - обработчик и создатель в одном файле!
 * ViewElementBuilder должен хранить простые хелперы
 *
 * наследование от Zone сделано для совместимости очистки на destroy
 * **/
export class SpiderSettingsDialogManager extends Phaser.GameObjects.Zone {
    private sceneEvents: SceneEvents<IGameEvents>;

    constructor(private props: IProps) {
        super(props.scene, 0, 0);
        this.sceneEvents = new SceneEvents<IGameEvents>({scene: props.scene});
        this.sceneEvents.on("onSettingsButtonClick", () => {
            this.openDialog();
        });
    }

    destroy(fromScene?: boolean) {
        super.destroy(fromScene);
        // отписывается только от своих подписок
        this.sceneEvents.unSubscribeAll();
    }

    openDialog() {
        const {scene} = this.props;
        const animationDuration = gameConfig.dialogs?.animationShowDuration ?? 180;
        /** запускаем диалог в новой сцене **/
        openCommonModalInScene({
            parentScene: scene,
            createContent: (scene) => this.createDialog(scene),
            props: {
                animationDuration,
                isCloseOnOverlayClick: true
            },
        });
    }

    createDialog(scene: Phaser.Scene) {
        const {scene: parentScene} = this.props;
        const builder = new ViewElementBuilder(scene);
        const gameService = GameServiceProvider.get();
        const initialSettings = gameService.getPlayerData().settings;

        const container = scene.add.container(0, 0, []);
        const bg = builder.dialogBgLightNine({width: 857, height: 577});
        const titleText = getLocalizedText('settings.title');
        const title = builder.dialogTitle({label: titleText});

        /** событие передается в сцену текущую то есть открытую **/
        const closeButton = builder.buttonCloseDialog(() => {
            scene.events.emit(CommonModal.EVENT_CLOSE_COMMAND)
        });

        const soundButton = builder.buttonSwitchSound((isSoundOn) => {
            const nextSettings: ISettingsState = {
                ...gameService.getPlayerData().settings,
                isSoundOn,
            };
            gameService.setPlayerData({settings: nextSettings});
            /** тут событие передается в сцену родительскую
             * чтобы она могла обновиться если не на паузе **/
            parentScene.events.emit("gameSettingsUpdated", nextSettings);
        });
        soundButton.switch(initialSettings.isSoundOn);

        const musicButton = builder.buttonSwitchMusic((isMusicOn) => {
            const nextSettings: ISettingsState = {
                ...gameService.getPlayerData().settings,
                isMusicOn,
            };
            gameService.setPlayerData({settings: nextSettings});
            /** тут событие передается в сцену родительскую
             * чтобы она могла обновиться если не на паузе **/
            parentScene.events.emit("gameSettingsUpdated", nextSettings);
        });
        musicButton.switch(initialSettings.isMusicOn);

        const align = new Align();
        align.anchor(bg).centerX(title).topIn(title, 40);
        align.rightIn(closeButton, -20).topIn(closeButton, 20)

        const buttonGroup = layoutChain({
            children: [soundButton, musicButton],
            alignToAnchor: AlignMethod.CENTER_X,
            alignToNext: AlignMethod.BOTTOM_TO,
            nextOffsetY: 20
        });

        align.anchor(bg).centerX(buttonGroup).topIn(buttonGroup, 167);

        container.add([
            bg, title, closeButton, soundButton, musicButton
        ])
        return container;
    }
}
