import {
  cardBacksChibiPack01AutoAssetsConst,
  preloadCardBacksChibiPack01Assets,
} from "../../../assets/figmaAssets/card-backs-chibi-pack-01-assets";
import {
  cardChibi01AutoAssetsConst,
  preloadCardChibi01Assets,
} from "../../../assets/figmaAssets/card-chibi-01-assets";
import {
  cardClassic01AutoAssetsConst,
  preloadCardClassic01Assets,
} from "../../../assets/figmaAssets/card-classic-01-assets";
import {
  IThemedSpiderCardBackTheme,
  ThemedSpiderCardFaceImageMap,
} from "../../../common/games/spider/cards/ThemedSpiderCard";
import { GamePlayCardTheme } from "./types";

const gamePlayCardFaceImageMapByTheme: Record<GamePlayCardTheme, ThemedSpiderCardFaceImageMap> = {
  [GamePlayCardTheme.chibi]: cardChibi01AutoAssetsConst,
  [GamePlayCardTheme.classic]: cardClassic01AutoAssetsConst,
};

export type GamePlayCardBackAssetName = keyof typeof cardBacksChibiPack01AutoAssetsConst;

const gamePlayCardDefaultBackAssetName: GamePlayCardBackAssetName = "cardBackClassic1";

export function preloadGamePlayCardAssets(scene: Phaser.Scene): void {
  preloadCardChibi01Assets(scene);
  preloadCardClassic01Assets(scene);
  preloadCardBacksChibiPack01Assets(scene);
}

export function getGamePlayCardFaceImageMap(theme: GamePlayCardTheme): ThemedSpiderCardFaceImageMap {
  return gamePlayCardFaceImageMapByTheme[theme];
}

export function getGamePlayCardBackTheme(
  backAssetName: GamePlayCardBackAssetName,
): IThemedSpiderCardBackTheme {
  const backAsset = cardBacksChibiPack01AutoAssetsConst[backAssetName];
  return {
    textureName: backAsset.url,
    frameName: backAsset.frameName,
  };
}

export function getGamePlayCardBackAssetNames(): GamePlayCardBackAssetName[] {
  return Object.keys(cardBacksChibiPack01AutoAssetsConst) as GamePlayCardBackAssetName[];
}

export function createGamePlayCardDimmedImage(scene: Phaser.Scene): Phaser.GameObjects.Image {
  return new Phaser.GameObjects.Image(
    scene,
    0,
    0,
    cardChibi01AutoAssetsConst.dimmedCard.url,
    cardChibi01AutoAssetsConst.dimmedCard.frameName,
  );
}

export function getGamePlayCardDefaultBackTheme(): IThemedSpiderCardBackTheme {
  return getGamePlayCardBackTheme(gamePlayCardDefaultBackAssetName);
}
