import {SoundKey} from "../../logic";
import {GameServiceProvider} from "../../services";
import {BgAssetManager, SceneSoundManager} from "../shared";
import {SpiderGameScenes} from "../scenes";
import {SpiderStartView} from "./SpiderStartView";
import {SpiderGameOverDialogManager, SpiderSettingsDialogManager} from '../dialog';

export class SpiderStartScene extends Phaser.Scene {
    constructor() {
        super(SpiderGameScenes.SpiderStart);
    }

    preload() {
    }

    create() {
        const scene = this;
        const musicVolume = GameServiceProvider.get().getGameConfig().audio.musicVolume;
        new BgAssetManager({scene});
        new SceneSoundManager({
            scene,
            musicSoundKey: SoundKey.music,
            musicVolume,
        });
        new SpiderSettingsDialogManager({scene});
        new SpiderGameOverDialogManager({scene});
        new SpiderStartView({scene});
    }
}
